const scenarios = {"retiro": [["Retiro válido", "Paquete listo + confirmación de la persona responsable.", "Registrar la fecha y marcar el paquete como retirado.", "Regla R5"], ["Sin confirmación", "Paquete listo, sin confirmación de la persona responsable.", "Mantener el estado y pedir revisión humana.", "Decisión del grupo"], ["Retiro repetido", "El paquete ya tiene fecha y estado retirado.", "Conservar el registro original y pedir revisión humana.", "Caso límite propuesto"]], "aviso": [["Fallo confirmado", "El servicio informa que el aviso no pudo enviarse.", "Mostrar error, pedir intervención humana y no marcar como enviado.", "Regla R6"], ["Envío confirmado", "El servicio confirma explícitamente el envío.", "Registrar el aviso como enviado.", "Decisión del grupo"], ["Resultado incierto", "No hay confirmación de éxito ni un fallo concluyente.", "No afirmar éxito; mostrar incertidumbre y pedir revisión humana.", "Caso límite propuesto"]]};
function showCase(flow,index){const item=scenarios[flow][index];const box=document.getElementById('result-'+flow);box.replaceChildren();for(const [tag,text] of [['span',item[3]],['p',item[1]],['strong',item[2]]]){const el=document.createElement(tag);el.textContent=text;box.append(el);}document.querySelectorAll('[data-flow="'+flow+'"]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.case)===index)));}
document.querySelectorAll('.case-button').forEach(button=>button.addEventListener('click',()=>showCase(button.dataset.flow,Number(button.dataset.case))));Object.keys(scenarios).forEach(flow=>showCase(flow,0));
